def is_convex_polygon(points):
    # Guard against degenerate cases or incorrect input
    if len(points) < 3 or any(len(p) != 2 for p in points):
        return False
    if len(points) == 3:
        # A triangle is convex by definition (unless collinear)
        return not is_collinear(points[0], points[1], points[2])

    # Pick a base point and compare the signs of cross products
    base = points[0]
    sign = None
    for i in range(1, len(points) - 1):
        cross = cross_product(base, points[i], points[i + 1])
        if cross == 0:
            # Collinear points make the polygon non-convex
            return False
        if sign is None:
            sign = 1 if cross > 0 else -1
        elif (sign == 1 and cross < 0) or (sign == -1 and cross > 0):
            return False
    return True

def cross_product(a, b, c):
    # (b - a) cross (c - a), y-component only
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])

def is_collinear(a, b, c):
    return cross_product(a, b, c) == 0
```

