def is_checkerboard(grid):
    """Determines whether a 2D grid of integers is in checkerboard form."""
    # Handle the special cases with no rows, one row, or one column.
    if not grid or not grid[0]:
        return True
    if len(grid) == 1:
        return len(grid[0]) <= 1
    # Get the expected values for the first two cells of the first row.
    expected = {(0, 0): grid[0][0], (0, 1): grid[0][1]}
    # Merge them into a set and check if it has exactly two values.
    values = set(grid[0])
    if len(values) != 2 or values != set(expected.values()):
        return False
    # Check every cell in the grid.
    for row in range(len(grid)):
        for col in range(len(grid[0])):
            # Skip the first two cells, which are our reference.
            if row == 0 and col < 2:
                continue
            # Determine the expected value based on (row + col) % 2.
            expected_value = grid[0][0] if (row + col) % 2 == 0 else grid[0][1]
            if grid[row][col] != expected_value:
                return False
    return True
