The function checks for a checkerboard by comparing each cell's value to its expected parity based on its (row + column) index, rather than directly comparing values.

```python
def is_checkerboard(grid):
    """Check whether a 2D grid forms a checkerboard of exactly two alternating values."""
    if not grid or not grid[0]:
        return True

    # For each cell, check its four neighbors only if they exist.
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            val = grid[i][j]
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < len(grid) and 0 <= nj < len(grid[0]):
                    if grid[ni][nj] == val:
                        return False

    # If exactly two values are used, return True.
    # Otherwise, it's not a checkerboard of exactly two values.
    values = set()
    for row in grid:
        values.update(row)
    return len(values) == 2
```

