def shift_rows_down(grid, k):
    height = len(grid)
    if height == 0:
        return grid
    rotate_by = k % height
    if rotate_by == 0:
        return [row[:] for row in grid]
    return [grid[-rotate_by]] + grid[:-rotate_by]
