def inventory_counts(events):
    if not events:
        return {}

    counts = {}
    items_to_check = set(item for item, _ in events)

    # Special case for the first item in the first event
    first_item = events[0][0]
    first_delta = events[0][1]
    if first_delta >= 0:
        counts[first_item] = first_delta
    else:
        counts[first_item] = 0

    # Process other events, skipping those that would drop below 0
    for item, delta in events[1:]:
        if item not in counts:
            if delta >= 0:
                counts[item] = delta
            else:
                counts[item] = 0
        else:
            if counts[item] + delta >= 0:
                counts[item] += delta

    return {key: counts[key] for key in items_to_check}
```

