def robot_vacuum_cleaned(commands, obstacles):
    # Convert obstacles to a set of tuples for fast lookups
    obstacle_set = set(obstacles)
    # Set of distinct cells the robot has cleaned
    cleaned = {(0, 0)}
    # Initial position and direction
    x, y = 0, 0
    facing = 0  # 0 is north, 1 is east, 2 is south, 3 is west

    for cmd in commands:
        if cmd == 'L':
            facing = (facing - 1) % 4
        elif cmd == 'R':
            facing = (facing + 1) % 4
        elif cmd == 'F':
            # Determine the direction and compute the new position
            if facing == 0:
                new_x, new_y = x, y + 1
            elif facing == 1:
                new_x, new_y = x + 1, y
            elif facing == 2:
                new_x, new_y = x, y - 1
            elif facing == 3:
                new_x, new_y = x - 1, y
            # If the new position is not an obstacle, move there
            if (new_x, new_y) not in obstacle_set:
                x, y = new_x, new_y
            # Add current cell (whether moved or not) to cleaned set
            cleaned.add((x, y))

    return len(cleaned)
```

