def parking_garage_fees(events, rate):
    # Simulate the parking garage for a single día
    parked = {}
    fees = {}

    for op, car_id, time in events:
        if op == 'enter':
            # Ignore if the car is already parked
            if car_id not in parked:
                parked[car_id] = time
        elif op == 'exit':
            # Compute fee and remove if the car is parked
            if car_id in parked:
                duration = time - parked[car_id]
                fees[car_id] = duration * rate
                del parked[car_id]

    return fees
