def coffee_machine_credit(events, prices, stock):
    credit = 0
    total_dispensed = 0
    # Make a copy to avoid modifying the input stock
    final_stock = dict(stock)
    for op, value in events:
        if op == "insert":
            credit += value
        elif op == "select":
            drink = value
            if (
                final_stock[drink] > 0
                and credit >= prices[drink]
            ):
                final_stock[drink] -= 1
                credit -= prices[drink]
                total_dispensed += 1
    return (credit, final_stock, total_dispensed)
